// --- Toast Notification Component ---
const Toast = ({ message, show, type = 'success' }) => {
    if (!show) return null;
    const style = type === 'success' ? styles.toastSuccess : styles.toastError;
    return <div style={{...styles.toast, ...style}}>{message}</div>;
};


// --- Main Per-delivery Allocation Tab Component ---
export default function PerDeliveryAllocationTab({ term, onAllocationChange }) {
    // --- State Management ---
    const [firstOfferingOfYear, setFirstOfferingOfYear] = useState('Yes');
    const [deliveries, setDeliveries] = useState([
        { id: 1, deliveryLocation: 'CTN', lecturer: 'Mary', weeklyLectureTime: 2, earlyCareerLoading: 'No', permanent: true },
        { id: 2, deliveryLocation: 'PEN', lecturer: 'Mary', weeklyLectureTime: 0, earlyCareerLoading: 'No' },
        { id: 3, deliveryLocation: 'KWD', lecturer: 'Mary', weeklyLectureTime: 0, earlyCareerLoading: 'No' },
    ]);

    // State to manage editing, backups for cancellation, validation errors, and toasts
    const [editingId, setEditingId] = useState(null);
    const [backupData, setBackupData] = useState(null); // Used to restore data on cancel
    const [validationErrors, setValidationErrors] = useState({});
    const [toast, setToast] = useState({ show: false, message: '', type: 'success' });

    // --- Calculation Logic ---
    const calculatedData = useMemo(() => {
        const termMultiplier = 1.0;
        const getEarlyCareerBonus = (loadingType) => {
            const map = {
                "Yes - materials provided": 0.02,
                "Yes - materials need major rewriting": 0.03,
                "Yes - no materials provided": 0.04,
            };
            return map[loadingType] || 0;
        };
        const individualAllocations = deliveries.map(d => {
            const earlyCareerBonus = getEarlyCareerBonus(d.earlyCareerLoading);
            const time = Number(d.weeklyLectureTime) || 0;
            return 0.01 + (time * termMultiplier * 0.01) + earlyCareerBonus;
        });
        const sumOfIndividualAllocations = individualAllocations.reduce((sum, alloc) => sum + alloc, 0);
        let firstOfferingBonus = 0;
        if (firstOfferingOfYear === 'Yes' && deliveries.length > 0) {
            const maxLectureTime = Math.max(...deliveries.map(d => Number(d.weeklyLectureTime) || 0));
            firstOfferingBonus = 0.01 * termMultiplier * maxLectureTime;
        }
        const totalPerDeliveryAllocation = sumOfIndividualAllocations + firstOfferingBonus;
        return { total: totalPerDeliveryAllocation, individuals: individualAllocations };
    }, [deliveries, firstOfferingOfYear, term]);

    // --- Effect to notify parent of allocation changes ---
    useEffect(() => {
        if (onAllocationChange) {
            onAllocationChange(calculatedData.total);
        }
    }, [calculatedData.total, onAllocationChange]);

    // --- Toast display logic ---
    const showToast = (message, type = 'success') => {
        setToast({ show: true, message, type });
        setTimeout(() => setToast({ show: false, message: '', type: 'success' }), 4000);
    };

    // --- Input Validation Logic ---
    const validateRow = (delivery) => {
        const errors = {};
        const nameRegex = /^[a-zA-Z\s]*$/;

        if (!delivery.deliveryLocation || delivery.deliveryLocation.trim() === '') {
            errors.deliveryLocation = 'Delivery cannot be empty.';
        } else if (!nameRegex.test(delivery.deliveryLocation)) {
            errors.deliveryLocation = 'Delivery cannot have numbers or special characters.';
        }

        if (!delivery.lecturer || delivery.lecturer.trim() === '') {
            errors.lecturer = 'Lecturer cannot be empty.';
        } else if (!nameRegex.test(delivery.lecturer)) {
            errors.lecturer = 'Lecturer cannot have numbers or special characters.';
        }

        const time = delivery.weeklyLectureTime;
        if (time !== '' && (isNaN(time) || Number(time) < 0)) {
            errors.weeklyLectureTime = 'Hours must be a positive number.';
        }

        return errors;
    };


    // --- Event Handlers ---
    const handleAdd = () => {
        // Prevent adding a new row if one is already being edited
        if (editingId) {
            showToast('Please save or cancel the current row first.', 'error');
            return;
        }
        const newId = `new-${Date.now()}`; // Use a temporary unique ID
        const newDelivery = {
            id: newId,
            deliveryLocation: '',
            lecturer: '',
            weeklyLectureTime: '', // Start as empty string for placeholder
            earlyCareerLoading: 'No',
            isNew: true,
        };
        setDeliveries([...deliveries, newDelivery]);
        setEditingId(newId);
    };

    const handleEdit = (id) => {
        if (editingId) {
            showToast('Please save or cancel the current row first.', 'error');
            return;
        }
        setBackupData(JSON.parse(JSON.stringify(deliveries))); // Deep copy for restoration
        setEditingId(id);
    };

    const handleCancel = (id) => {
        if (backupData) { // It was an edit of an existing row
            setDeliveries(backupData);
            setBackupData(null);
        } else { // It was a new add
            setDeliveries(deliveries.filter(d => d.id !== id));
        }
        setEditingId(null);
        setValidationErrors({});
    };

    const handleSave = (id) => {
        const currentRow = deliveries.find(d => d.id === id);
        const errors = validateRow(currentRow);

        if (Object.keys(errors).length > 0) {
            setValidationErrors({ [id]: errors });
            showToast('Please fix the errors before saving.', 'error');
            return;
        }

        // Finalize data before saving
        const finalDeliveries = deliveries.map(d => {
            if (d.id === id) {
                // Default empty time to 0, generate permanent ID if new
                const permanentId = d.isNew ? Math.max(0, ...deliveries.map(del => typeof del.id === 'number' ? del.id : 0)) + 1 : id;
                return { ...d, weeklyLectureTime: d.weeklyLectureTime === '' ? 0 : Number(d.weeklyLectureTime), id: permanentId, isNew: false };
            }
            return d;
        });

        setDeliveries(finalDeliveries);
        setEditingId(null);
        setBackupData(null);
        setValidationErrors({});
        showToast('Record saved successfully.');
    };

    const handleDelete = (id) => {
        if (window.confirm('Are you sure you want to delete this delivery?')) {
            setDeliveries(deliveries.filter(d => d.id !== id));
            showToast('Delivery deleted successfully.');
        }
    };

    const handleDeliveryChange = (id, field, value) => {
        setDeliveries(deliveries.map(d =>
            d.id === id ? { ...d, [field]: value } : d
        ));
        // Clear validation error for the field being changed
        if (validationErrors[id] && validationErrors[id][field]) {
            const newErrors = { ...validationErrors[id] };
            delete newErrors[field];
            setValidationErrors({ ...validationErrors, [id]: newErrors });
        }
    };

    const earlyCareerOptions = ["No", "Yes - materials provided", "Yes - materials need major rewriting", "Yes - no materials provided"];

    // --- Render ---
    return (
        <div style={styles.container}>
             <div style={styles.formGroupColumn}>
                <label style={{...styles.label, marginBottom: '0.5rem'}} htmlFor="totalAllocation">
                    Per-delivery Allocation
                    <InfoIcon tooltip="The per-delivery allocation covers tasks at the large group level..."/>
                </label>
                <input type="text" id="totalAllocation" readOnly style={styles.totalInput} value={`${(calculatedData.total * 100).toFixed(1)}%`}/>
            </div>

            <div style={styles.formGroupWithBorder}>
                <label style={styles.label} htmlFor="firstOffering">
                    First offering of the calendar year
                    <InfoIcon tooltip="List all deliveries and, for each delivery, indicate the lecturer..."/>
                </label>
                <select id="firstOffering" style={styles.select} value={firstOfferingOfYear} onChange={(e) => setFirstOfferingOfYear(e.target.value)}>
                    <option value="Yes">Yes</option>
                    <option value="No">No</option>
                </select>
            </div>

            <div style={styles.tableActions}>
                 <button style={styles.addButton} onClick={handleAdd}>+ Add</button>
            </div>

            <div style={styles.tableContainer}>
                {/* Table Header */}
                <div style={styles.tableHeader}>
                    <div style={{...styles.tableCell, flex: 0.7}}>Actions</div>
                    <div style={{...styles.tableCell, flex: 1}}>Delivery</div>
                    <div style={{...styles.tableCell, flex: 2}}>Lecturer / Campus Coordinator</div>
                    <div style={{...styles.tableCell, flex: 2}}>Weekly lecture time (hours)</div>
                    <div style={{...styles.tableCell, flex: 2.5}}>Early career academic loading</div>
                    <div style={{...styles.tableCell, flex: 1, justifyContent: 'flex-end'}}>Allocation</div>
                </div>

                {/* Table Body */}
                {deliveries.map((delivery, index) => {
                    const isEditing = editingId === delivery.id;
                    const isPermanent = delivery.permanent === true;
                    const errors = validationErrors[delivery.id] || {};

                    return (
                        <div key={delivery.id} style={isPermanent ? {...styles.tableRow, ...styles.disabledRow} : styles.tableRow}>
                            <div style={{...styles.tableCell, flex: 0.7, display: 'flex', gap: '12px' }}>
                                {isEditing ? (
                                    <>
                                        <CheckIcon onClick={() => handleSave(delivery.id)} />
                                        <CancelIcon onClick={() => handleCancel(delivery.id)} />
                                    </>
                                ) : (
                                    <>
                                        <EditIcon onClick={() => handleEdit(delivery.id)} disabled={isPermanent} />
                                        <DeleteIcon onClick={() => handleDelete(delivery.id)} disabled={isPermanent} />
                                    </>
                                )}
                            </div>
                            <div style={{...styles.tableCell, flex: 1, flexDirection: 'column', alignItems: 'flex-start'}}>
                                <input type="text" style={{...styles.tableInput, ...(errors.deliveryLocation && styles.inputError)}} value={delivery.deliveryLocation} readOnly={!isEditing} onChange={(e) => handleDeliveryChange(delivery.id, 'deliveryLocation', e.target.value)} />
                                {errors.deliveryLocation && <span style={styles.errorText}>{errors.deliveryLocation}</span>}
                            </div>
                            <div style={{...styles.tableCell, flex: 2, flexDirection: 'column', alignItems: 'flex-start'}}>
                                <input type="text" style={{...styles.tableInput, ...(errors.lecturer && styles.inputError)}} value={delivery.lecturer} readOnly={!isEditing} onChange={(e) => handleDeliveryChange(delivery.id, 'lecturer', e.target.value)} />
                                {errors.lecturer && <span style={styles.errorText}>{errors.lecturer}</span>}
                            </div>
                             <div style={{...styles.tableCell, flex: 2, flexDirection: 'column', alignItems: 'flex-start'}}>
                                <input type="text" placeholder="0" style={{...styles.tableInput, ...(errors.weeklyLectureTime && styles.inputError)}} value={delivery.weeklyLectureTime} readOnly={!isEditing} onChange={(e) => handleDeliveryChange(delivery.id, 'weeklyLectureTime', e.target.value)} />
                                {errors.weeklyLectureTime && <span style={styles.errorText}>{errors.weeklyLectureTime}</span>}
                            </div>
                            <div style={{...styles.tableCell, flex: 2.5}}>
                                <select style={styles.tableSelect} value={delivery.earlyCareerLoading} disabled={!isEditing} onChange={(e) => handleDeliveryChange(delivery.id, 'earlyCareerLoading', e.target.value)}>
                                    {earlyCareerOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                                </select>
                            </div>
                            <div style={{...styles.tableCell, flex: 1, justifyContent: 'flex-end'}}>
                                <input type="text" readOnly style={{...styles.tableInput, ...styles.readOnlyInput}} value={`${(calculatedData.individuals[index] * 100).toFixed(1)}%`}/>
                            </div>
                        </div>
                    );
                })}
            </div>

            <Toast message={toast.message} show={toast.show} type={toast.type} />
        </div>
    );
}

